def get_all_pantheon_zeta_agents() -> list:
    agents = []
    for cat_id, cat in PANTHEON_ZETA_CATEGORIES.items():
        for agent in cat["agents"]:
            agents.append({"id": agent["id"], "name": agent["name"], "role": agent["role"], "specialty": agent["specialty"], "color": agent["color"], "category": cat_id, "category_name": cat["name"]})
    return agents

def get_pantheon_zeta_prompt(agent_id: str, context: str) -> tuple:
    for cat_id, cat in PANTHEON_ZETA_CATEGORIES.items():
        for agent in cat["agents"]:
            if agent["id"] == agent_id:
                return (f"{agent['persona']}\n\nYou are part of the Expert Pantheon (Zeta Division).", f"As {agent['name']} ({agent['role']}), apply your expertise to:\n\n{context}")
    return ("You are a domain expert.", f"Analyze: {context}")
